    /// <summary>
    /// Minimal localisation: UI code calls Loc.T("English text") and gets the translation for the selected language,
    /// falling back to English when a string has no translation. Languages: English, Espanol, Francais, Deutsch.
    /// </summary>
    public static class Loc
    {
        public const int LanguageCount = 4;
        static readonly string[] names = { "ENGLISH", "ESPAÑOL", "FRANÇAIS", "DEUTSCH" };
        public static string LanguageName(int i) { return names[UnityEngine.Mathf.Clamp(i, 0, LanguageCount - 1)]; }

        static Dictionary<string, string[]> map;

        public static string T(string en)
        {
            int lang = GameSettings.Language;
            if (lang <= 0 || string.IsNullOrEmpty(en)) return en;
            if (map == null) Build();
            string[] tr;
            if (map.TryGetValue(en, out tr) && lang - 1 < tr.Length && !string.IsNullOrEmpty(tr[lang - 1])) return tr[lang - 1];
            return en;
        }

        static void Build()
        {
            map = new Dictionary<string, string[]>();
            for (int i = 0; i + 3 < Table.Length; i += 4)
                map[Table[i]] = new[] { Table[i + 1], Table[i + 2], Table[i + 3] };
        }

